/**
 * Briven function — list API keys for a project.
 */
import { query, type Ctx } from "@briven/cli/server";

export default query(
  async (
    ctx: Ctx,
    input: { projectId: string },
  ): Promise<
    Array<{
      id: string;
      name: string;
      keyPrefix: string;
      lastUsedAt: string | null;
      revokedAt: string | null;
      createdAt: string;
    }>
  > => {
    return (await ctx
      .db("apiKey")
      .select(["id", "name", "keyPrefix", "lastUsedAt", "revokedAt", "createdAt"])
      .where({ projectId: input.projectId })
      .orderBy("createdAt", "desc")
      .limit(50)) as Array<{
      id: string;
      name: string;
      keyPrefix: string;
      lastUsedAt: string | null;
      revokedAt: string | null;
      createdAt: string;
    }>;
  },
);

functions.createApiKey.ts:
/**
 * Briven function — create an API key record.
 * The plaintext secret is hashed by the caller; only the hash is stored.
 */
import { mutation, type Ctx } from "@briven/cli/server";

export default mutation(
  async (
    ctx: Ctx,
    input: {
      id: string;
      projectId: string;
      userId: string;
      name: string;
      keyPrefix: string;
      keyHash: string;
    },
  ): Promise<{ id: string; name: string; keyPrefix: string; createdAt: string }> => {
    const now = new Date().toISOString();

    await ctx.db("apiKey").insert({
      id: input.id,
      projectId: input.projectId,
      userId: input.userId,
      name: input.name,
      keyPrefix: input.keyPrefix,
      keyHash: input.keyHash,
      createdAt: now,
    });

    ctx.log.info("api_key_created", { keyId: input.id, projectId: input.projectId, userId: input.userId });

    return {
      id: input.id,
      name: input.name,
      keyPrefix: input.keyPrefix,
      createdAt: now,
    };
  },
);

functions.listProjects.ts:
/**
 * Briven function — list projects for an organization.
 */
import { query, type Ctx } from "@briven/cli/server";

export default query(
  async (
    ctx: Ctx,
    input: { organizationId: string },
  ): Promise<Array<{ id: string; name: string; slug: string }>> => {
    try {
      return (await ctx
        .db("project")
        .select(["id", "name", "slug"])
        .where({ organizationId: input.organizationId })
        .orderBy("createdAt", "desc")
        .limit(50)) as Array<{ id: string; name: string; slug: string }>;
    } catch (e) {
      ctx.log.warn("list_projects_failed", { error: String(e) });
      return [];
    }
  },
);

functions.revokeApiKey.ts:
/**
 * Briven function — revoke a single API key scoped by id AND user_id.
 */
import { mutation, type Ctx } from "@briven/cli/server";

export default mutation(
  async (
    ctx: Ctx,
    input: { id: string; userId: string },
  ): Promise<{ id: string; revokedAt: string }> => {
    const revokedAt = new Date().toISOString();

    const result = (await ctx
      .db("apiKey")
      .update({ revokedAt })
      .where({ id: input.id, userId: input.userId })
      .returning(["id"])) as Array<{ id: string }>;

    if (result.length === 0) {
      throw new Error("API key not found or access denied");
    }

    ctx.log.info("api_key_revoked", { keyId: input.id, userId: input.userId });

    return { id: input.id, revokedAt };
  },
);

