/**
 * Briven function — create a project under an organization.
 */
import { mutation, type Ctx } from "@briven/cli/server";

export default mutation(
  async (
    ctx: Ctx,
    input: { organizationId: string; name: string; slug: string },
  ): Promise<{ id: string; organizationId: string; name: string; slug: string }> => {
    const id = crypto.randomUUID();

    await ctx.db("project").insert({
      id,
      organizationId: input.organizationId,
      name: input.name,
      slug: input.slug,
    });

    ctx.log.info("project_created", {
      projectId: id,
      organizationId: input.organizationId,
    });

    return { id, organizationId: input.organizationId, name: input.name, slug: input.slug };
  },
);

functions.getApiKeyByPrefix.ts:
/**
 * Briven function — fetch a single active API key by its public prefix.
 * Used by the ingest guard cache-warm path.
 */
import { query, type Ctx } from "@briven/cli/server";

export default query(
  async (
    ctx: Ctx,
    input: { keyPrefix: string },
  ): Promise<{
    id: string;
    projectId: string;
    userId: string;
    keyHash: string;
    organizationId: string;
  } | null> => {
    const rows = (await ctx
      .db("apiKey")
      .select(["id", "projectId", "userId", "keyHash"])
      .where({ keyPrefix: input.keyPrefix, revokedAt: null })
      .limit(1)) as Array<{
      id: string;
      projectId: string;
      userId: string;
      keyHash: string;
    }>;

    if (rows.length === 0) {
      return null;
    }

    const key = rows[0];

    // Resolve org via project.
    const projects = (await ctx
      .db("project")
      .select(["organizationId"])
      .where({ id: key.projectId })
      .limit(1)) as Array<{ organizationId: string }>;

    return {
      ...key,
      organizationId: projects[0]?.organizationId ?? "",
    };
  },
);

functions.listOrganizations.ts:
/**
 * Briven function — list organizations the user is a member of.
 */
import { query, type Ctx } from "@briven/cli/server";

export default query(
  async (
    ctx: Ctx,
    input: { userId: string },
  ): Promise<Array<{ id: string; name: string; slug: string; role: string }>> => {
    const memberships = (await ctx
      .db("member")
      .select(["organizationId", "role"])
      .where({ userId: input.userId })
      .orderBy("createdAt", "desc")) as Array<{ organizationId: string; role: string }>;

    if (memberships.length === 0) {
      return [];
    }

    const orgIds = memberships.map((m) => m.organizationId);
    const orgs = (await ctx
      .db("organization")
      .select(["id", "name", "slug"])
      .where({ id: orgIds })
      .orderBy("createdAt", "desc")) as Array<{ id: string; name: string; slug: string }>;

    return orgs.map((org) => {
      const membership = memberships.find((m) => m.organizationId === org.id);
      return { ...org, role: membership?.role ?? "member" };
    });
  },
);

