/**
 * Briven function — count active API keys for a project.
 */
import { query, type Ctx } from "@briven/cli/server";

export default query(
  async (ctx: Ctx, input: { projectId: string }): Promise<number> => {
    const rows = (await ctx
      .db("apiKey")
      .select(["id"])
      .where({ projectId: input.projectId, revokedAt: null })) as Array<{ id: string }>;

    return rows.length;
  },
);

functions.createOrganization.ts:
/**
 * Briven function — create an organization.
 * The caller must pass the authenticated userId; this function is invoked
 * from the Next.js API route using the project API key.
 */
import { mutation, type Ctx } from "@briven/cli/server";

export default mutation(
  async (
    ctx: Ctx,
    input: { userId: string; name: string; slug: string },
  ): Promise<{ id: string; name: string; slug: string }> => {
    const id = crypto.randomUUID();

    await ctx.db("organization").insert({
      id,
      name: input.name,
      slug: input.slug,
    });

    await ctx.db("member").insert({
      id: crypto.randomUUID(),
      organizationId: id,
      userId: input.userId,
      role: "owner",
    });

    ctx.log.info("organization_created", { organizationId: id, userId: input.userId });

    return { id, name: input.name, slug: input.slug };
  },
);

functions.touchApiKeyLastUsed.ts:
/**
 * Briven function — update the lastUsedAt timestamp of an API key.
 * Called debounced from the ingest guard.
 */
import { mutation, type Ctx } from "@briven/cli/server";

export default mutation(async (ctx: Ctx, input: { id: string }) => {
  await ctx
    .db("apiKey")
    .update({ lastUsedAt: new Date().toISOString() })
    .where({ id: input.id });

  return { ok: true };
});
